import os
import sys
import json
import time
import glob
import math
import random
import subprocess
import importlib.util
from typing import Generator, Dict, Any, Optional, List

def ensure_package(pkg: str, import_name: Optional[str] = None) -> None:
    name = import_name or pkg
    if importlib.util.find_spec(name) is None:
        subprocess.check_call([sys.executable, "-m", "pip", "install", "--upgrade", pkg])

def get_env(key: str) -> str:
    v = os.environ.get(key, "").strip()
    return v

def list_txt_files() -> List[str]:
    candidates = []
    for path in glob.glob("*.txt"):
        if os.path.isfile(path) and not path.lower().endswith(".jsonl") and os.path.basename(path).lower() != "dataset.jsonl":
            candidates.append(path)
    candidates.sort()
    return candidates

def chunk_stream_from_file(path: str, target_chars: int = 7000) -> Generator[str, None, None]:
    buf = []
    size = 0
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        for line in f:
            buf.append(line)
            size += len(line)
            if size >= target_chars:
                chunk = "".join(buf).strip()
                if chunk:
                    yield chunk
                buf = []
                size = 0
        final = "".join(buf).strip()
        if final:
            yield final

def brace_stream_json_extractor() -> Generator:
    buffer = []
    in_string = False
    escape = False
    depth = 0
    start_idx = None
    pos = 0
    while True:
        ch = (yield)
        buffer.append(ch)
        c = ch
        if start_idx is None:
            if c == "{":
                start_idx = pos
                depth = 1
                in_string = False
                escape = False
        else:
            if in_string:
                if escape:
                    escape = False
                elif c == "\\":
                    escape = True
                elif c == "\"":
                    in_string = False
            else:
                if c == "\"":
                    in_string = True
                elif c == "{":
                    depth += 1
                elif c == "}":
                    depth -= 1
                    if depth == 0:
                        s = "".join(buffer[start_idx:pos + 1])
                        yield ("OBJ", s)
                        del buffer[:pos + 1]
                        pos = -1
                        start_idx = None
        pos += 1

def validate_example(obj: Dict[str, Any]) -> bool:
    if not isinstance(obj, dict):
        return False
    messages = obj.get("messages")
    if not isinstance(messages, list) or len(messages) < 2:
        return False
    roles = [m.get("role") for m in messages if isinstance(m, dict)]
    if "user" not in roles or "assistant" not in roles:
        return False
    for m in messages:
        if not isinstance(m, dict):
            return False
        rc = m.get("role")
        cc = m.get("content")
        if rc not in ("system", "user", "assistant"):
            return False
        if not isinstance(cc, str):
            return False
        if cc.strip() == "":
            return False
    return True

def write_jsonl(fp, obj: Dict[str, Any]) -> None:
    line = json.dumps(obj, ensure_ascii=False, separators=(",", ":"))
    fp.write(line + "\n")
    fp.flush()
    os.fsync(fp.fileno())

def stable_sleep(base: float, attempt: int, cap: float = 20.0) -> None:
    t = min(cap, base * (2 ** max(0, attempt - 1)))
    jitter = t * 0.25
    time.sleep(t + random.uniform(0, jitter))

def build_system_prompt() -> str:
    return (
        "You are a top-tier data curator tasked with generating the highest-quality JSONL training data for a Jaide LLM, surpassing datasets used by GPT-5, Grok-4, Gemini-2.5, Claude-4.5, DeepSeek-3.2, Qwen-3, and LLaMA-4. "
        "From the provided text, extract and synthesize diverse, non-redundant, hallucination-free instruction–response pairs that demonstrate advanced reasoning, factual accuracy, multi-step problem solving, and broad knowledge depth. "
        "Include a mix of tasks: precise Q&A, multi-hop reasoning, chain-of-thought distilled final answers (no intermediate thoughts), step-by-step solutions with only final steps exposed, code tasks, mathematical derivations with results only, classification, explanation, rewriting, and structured output generation. "
        "Avoid copyrighted content beyond brief, non-identifiable facts; avoid personal data; avoid unsafe content; avoid any content that cannot be attributed to the input text. "
        "Each JSON object must follow this schema and be standalone: {\"messages\":[{\"role\":\"user\",\"content\":\"<instruction>\"},{\"role\":\"assistant\",\"content\":\"<ideal_answer>\"}]}. "
        "Do not include markdown fences or any text outside of pure JSON. "
        "Generate 12 to 18 JSON objects separated by single newlines, each on one line. "
        "Ensure linguistic clarity, correctness, and maximum utility for fine-tuning a Jaide architecture LLM. "
        "If the text is domain-specific, produce domain-accurate tasks and answers aligned to that domain."
    )

def build_user_prompt(chunk: str, file_name: str, chunk_index: int, total_chunks: int) -> str:
    return (
        "Source file: " + file_name + " | Chunk " + str(chunk_index) + " of " + str(total_chunks) + "\n"
        "Transform the following text into superior instruction–response pairs in strict JSONL format with one JSON object per line and no extra text:\n"
        + chunk
    )

def stream_completion(client, messages: List[Dict[str, str]], model: str, max_tokens: int, temperature: float, top_p: float, reasoning_effort: str):
    return client.chat.completions.create(
        messages=messages,
        model=model,
        stream=True,
        max_completion_tokens=max_tokens,
        temperature=temperature,
        top_p=top_p,
        reasoning_effort=reasoning_effort
    )

def process_chunk(client, out_fp, sys_prompt: str, user_prompt: str, model: str) -> int:
    max_tokens = 65536
    temperature = 0.04
    top_p = 0.03
    reasoning_effort = "high"
    messages = [
        {"role": "system", "content": sys_prompt},
        {"role": "user", "content": user_prompt}
    ]
    attempts = 0
    max_attempts = 6
    written = 0
    while attempts < max_attempts:
        try:
            stream = stream_completion(client, messages, model, max_tokens, temperature, top_p, reasoning_effort)
            extractor = brace_stream_json_extractor()
            next(extractor)
            for piece in stream:
                try:
                    delta = piece.choices[0].delta
                    content = getattr(delta, "content", None)
                except Exception:
                    content = None
                if not content:
                    continue
                for ch in content:
                    emitted = extractor.send(ch)
                    if isinstance(emitted, tuple) and emitted and emitted[0] == "OBJ":
                        raw = emitted[1]
                        try:
                            obj = json.loads(raw)
                        except Exception:
                            continue
                        if validate_example(obj):
                            write_jsonl(out_fp, obj)
                            written += 1
            if written > 0:
                return written
            attempts += 1
            stable_sleep(1.0, attempts)
        except Exception as e:
            attempts += 1
            if attempts >= max_attempts:
                return written
            stable_sleep(1.0, attempts)
    return written

def main():
    ensure_package("cerebras-cloud-sdk", "cerebras.cloud.sdk")
    import cerebras.cloud.sdk as cs
    from cerebras.cloud.sdk import Cerebras
    api_key = get_env("CEREBRAS_API_KEY")
    if not api_key:
        print("Hiba: A CEREBRAS_API_KEY nincs beállítva.", file=sys.stderr)
        sys.exit(1)
    files = list_txt_files()
    if not files:
        print("Hiba: Nem található feldolgozható .txt fájl a könyvtárban.", file=sys.stderr)
        sys.exit(1)
    client = Cerebras(api_key=api_key)
    out_path = "dataset.jsonl"
    processed_files = 0
    total_written = 0
    system_prompt = build_system_prompt()
    with open(out_path, "a", encoding="utf-8") as out_fp:
        for path in files:
            chunks = list(chunk_stream_from_file(path, 7000))
            if not chunks:
                continue
            total_chunks = len(chunks)
            processed_files += 1
            print("Fájl feldolgozása: " + path + " | Chunks: " + str(total_chunks))
            for idx, chunk in enumerate(chunks, start=1):
                user_prompt = build_user_prompt(chunk, os.path.basename(path), idx, total_chunks)
                wrote = process_chunk(client, out_fp, system_prompt, user_prompt, "gpt-oss-120b")
                total_written += wrote
                print("Chunk " + str(idx) + "/" + str(total_chunks) + " kész, érvényes sorok: " + str(wrote) + ", összesen: " + str(total_written))
    print("Kész. Fájlok: " + str(processed_files) + ", összes példány: " + str(total_written) + ", kimenet: " + out_path)

if __name__ == "__main__":
    main()
